const OF_GREY='#5C6577', OF_CORE='#DBE4FF', OF_CLAD='#F1F3F5';
/* the worked example's analog link (5.1), computed once */
const OF_K={R:0.6,m:0.5,B:6e6,q:1.602e-19,k:1.381e-23,T:300,Ft:Math.pow(10,0.3),Req:750,RIN:Math.pow(10,-14.3)};
const OF_cnr=dbm=>{const K=OF_K,Ip=K.R*1e-3*Math.pow(10,dbm/10),s=0.5*Math.pow(K.m*Ip,2),n=K.RIN*Ip*Ip*K.B+2*K.q*Ip*K.B+4*K.k*K.T*K.B*K.Ft/K.Req;return 10*Math.log10(s/n)};   // -10 dBm -> 59.6 dB, -20 dBm -> 42.1 dB
const OF_CEIL=10*Math.log10(0.5*OF_K.m*OF_K.m/(OF_K.RIN*OF_K.B));                          // 66.2 dB: the RIN ceiling
/* a small CNR-against-power graph: x from -30 to 0 dBm, y from 20 to 70 dB */
const OF_cnrGraph=(x0,y0,w,h,col)=>{const X=d=>x0+(d+30)/30*w,Y=v=>y0+h-(v-20)/50*h,pts=[];for(let d=-30;d<=0.001;d+=1)pts.push([X(d),Y(OF_cnr(d))]);
 return {X,Y,axes:OF_L(x0,y0,x0,y0+h,'#ADB5BD',3)+OF_L(x0,y0+h,x0+w,y0+h,'#ADB5BD',3),curve:OF_poly(pts,col,5),ceil:OF_L(x0,Y(OF_CEIL),x0+w,Y(OF_CEIL),MAG,3,'stroke-dasharray="8 6"')}};
/* the 5.2 budget: 28 dB available = fiber 13.2 + connectors 1.0 + splices 0.5 + margin 6 + spare 7.3 */
const OF_BUD=()=>[['fiber 13.2',13.2,BLU],['joints 1.5',1.5,ORG],['margin 6',6,'#F59F00'],['spare 7.3',7.3,GRN]];
const OF_stack=(x0,y0,kx,h,upto)=>{let x=x0,o='';OF_BUD().slice(0,upto).forEach(([,v,col])=>{o+=`<rect x="${x.toFixed(1)}" y="${y0}" width="${(v*kx).toFixed(1)}" height="${h}" fill="${col}" fill-opacity=".85" stroke="#FFFFFF" stroke-width="2"/>`;x+=v*kx});return o};
/* reels of fiber in a row: n reels from x0 to x1 at height y */
const OF_reels=(x0,x1,y,n,col)=>{const gw=(x1-x0)/n;let o='';for(let i=0;i<n;i++)o+=`<rect x="${(x0+i*gw+6).toFixed(1)}" y="${y-16}" width="${(gw-12).toFixed(1)}" height="32" rx="8" fill="${OF_CORE}" stroke="${col}" stroke-width="3"/>`+OF_T(x0+i*gw+gw/2,y+8,'10 km',{fs:22,fw:700,a:'middle',fill:col});return {o,gw}};
const OF_badge=(x,y,n,col,op=1)=>`<circle cx="${x.toFixed(1)}" cy="${y.toFixed(1)}" r="17" fill="${col}" fill-opacity="${op}"/>`+OF_T(x,y+8,String(n),{fs:22,fw:800,a:'middle',fill:'#FFFFFF'});
/* i²(t) for the signal: mean square of a sine is half its peak */
const OF_sq=(x0,x1,ytop,ybot,col)=>{const pts=[];for(let i=0;i<=120;i++){const t=i/120,v=Math.pow(Math.sin(2*Math.PI*2*t),2);pts.push([x0+t*(x1-x0),ybot-v*(ybot-ytop)])}return OF_poly(pts,col,4)};

